# Each repair addresses one output or one shared classification premise.
P={12:[],14:[],15:[],18:[]}
def add(i,label,old,new,cat,reason):P[i].append(dict(label=label,edits=[[old,new]],category=cat,reason=reason))
Q='Quiet Downgrade';I='Intent Misreading'
add(12,'delay_placeholder','NULL::UBIGINT avg_payment_delay_days',"CASE WHEN count(*) FILTER(WHERE t.account_type_name='Bank')>0 THEN 15+hash(l.entity_id)%30 ELSE NULL END avg_payment_delay_days",Q,'平均付款延迟整列NULL，未计算契约的15–44天模拟规则；无付款时NULL本来符合契约。')
add(12,'outstanding_days_placeholder','0::BIGINT days_since_last_outstanding',"coalesce(date_diff('day',last_outstanding_date,current_date),0)::BIGINT days_since_last_outstanding",Q,'未计算最后未付日期距今天数，直接填0。')
add(12,'relationship_months_placeholder','1::BIGINT relationship_duration_months',"coalesce(date_diff('month',min(t.accounting_period_ending),max(t.accounting_period_ending))+1,1)::BIGINT relationship_duration_months",Q,'关系持续月数固定1，未从首末交易日期计算。')
for label,expr,new in [('payment_performance_score','1 payment_performance_score',"CASE WHEN payment_ratio>=.95 THEN 5 WHEN payment_ratio>=.85 THEN 4 WHEN payment_ratio>=.75 THEN 3 WHEN payment_ratio>=.60 THEN 2 ELSE 1 END payment_performance_score"),('payment_timeliness_score','1 payment_timeliness_score',"CASE WHEN avg_payment_delay_days<=20 THEN 5 WHEN avg_payment_delay_days<=30 THEN 4 WHEN avg_payment_delay_days<=40 THEN 3 WHEN avg_payment_delay_days<=50 THEN 2 ELSE 1 END payment_timeliness_score"),('relationship_stability_score','1 relationship_stability_score',"CASE WHEN relationship_duration_months>=24 THEN 5 WHEN relationship_duration_months>=12 THEN 4 WHEN relationship_duration_months>=6 THEN 3 WHEN relationship_duration_months>=3 THEN 2 ELSE 1 END relationship_stability_score"),('transaction_frequency_score','1 transaction_frequency_score',"CASE WHEN total_transactions>=50 THEN 5 WHEN total_transactions>=25 THEN 4 WHEN total_transactions>=10 THEN 3 WHEN total_transactions>=5 THEN 2 ELSE 1 END transaction_frequency_score"),('total_credit_score','4 total_credit_score','payment_performance_score+payment_timeliness_score+relationship_stability_score+transaction_frequency_score total_credit_score'),('credit_rating',"'BB' credit_rating","CASE WHEN total_credit_score>=16 THEN 'AAA' WHEN total_credit_score>=13 THEN 'AA' WHEN total_credit_score>=10 THEN 'A' WHEN total_credit_score>=7 THEN 'BBB' ELSE 'BB' END credit_rating"),('risk_level',"'Minimal Risk' risk_level","CASE WHEN outstanding_balance>.3*total_expenses AND days_since_last_outstanding>60 THEN 'High Risk' WHEN outstanding_balance>.2*total_expenses AND days_since_last_outstanding>45 THEN 'Medium Risk' WHEN outstanding_balance>0 AND days_since_last_outstanding>30 THEN 'Low Risk' ELSE 'Minimal Risk' END risk_level")]:
 add(12,'placeholder_'+label,expr,new,Q,'该输出固定常量，未执行契约的分档或加总；按agent现有上游值单独恢复此输出，其他常量不联动改动。')
add(12,'credit_limit_placeholder','total_expenses*.1 recommended_credit_limit',"total_expenses*CASE WHEN total_credit_score>=16 THEN .5 WHEN total_credit_score>=13 THEN .4 WHEN total_credit_score>=10 THEN .3 WHEN total_credit_score>=7 THEN .2 ELSE .1 END recommended_credit_limit",Q,'额度只取支出的10%，遗漏契约依total_credit_score的倍率分档。')
add(14,'value_percentiles',"CASE WHEN cp.rev_pct>=.9 THEN 'Platinum' WHEN cp.rev_pct>=.7 THEN 'Gold' WHEN cp.rev_pct>=.5 THEN 'Silver' WHEN cp.rev_pct>=.3 THEN 'Bronze' ELSE 'Basic' END", "CASE WHEN cp.total_revenue>=(SELECT quantile_cont(total_revenue,.9) FROM cp) THEN 'Platinum' WHEN cp.total_revenue>=(SELECT quantile_cont(total_revenue,.7) FROM cp) THEN 'Gold' WHEN cp.total_revenue>=(SELECT quantile_cont(total_revenue,.5) FROM cp) THEN 'Silver' WHEN cp.total_revenue>=(SELECT quantile_cont(total_revenue,.3) FROM cp) THEN 'Bronze' ELSE 'Basic' END",I,'契约按总体收入percentile阈值含等号分档；agent用percent_rank的行位置比较，分别诊断是否造成当前差异。')
for col,src in [('avg_financial_health','overall_financial_health_score'),('avg_net_margin','net_profit_margin'),('avg_current_ratio','current_ratio')]:
 add(15,'passthrough_'+col,src+' '+col,'avg('+src+') OVER(PARTITION BY subsidiary_id) '+col,Q,'要求按subsidiary汇总平均，agent直接透传本行值；单观测组可能恰好相同。')
add(15,'improvement_placeholder',"'Maintain Current Performance' improvement_recommendation", "CASE WHEN current_ratio<1.5 AND net_profit_margin<.05 THEN 'Focus on Operations & Liquidity' WHEN current_ratio<1.5 THEN 'Improve Working Capital Management' WHEN net_profit_margin<.05 THEN 'Review Cost Structure' WHEN overdue_percentage>.15 THEN 'Strengthen Collections' ELSE 'Maintain Current Performance' END improvement_recommendation",Q,'改善建议固定Maintain Current Performance，未执行流动性/利润/逾期分支。')
add(18,'payment_recommendation_placeholder',"'Standard payment terms' payment_recommendation", "CASE WHEN overdue_payment_percentage>50 THEN 'Immediate payment processing review' WHEN overdue_payment_percentage>20 THEN 'Expedite payment processing' WHEN supplier_tier='Strategic Partner' THEN 'Consider early payment discounts' ELSE 'Standard payment terms' END payment_recommendation",Q,'付款建议固定Standard payment terms，未实现逾期比率与supplier_tier分支。')
add(18,'dependency_percentiles',"CASE WHEN pct>=.9 THEN 'Critical Dependency' WHEN pct>=.7 THEN 'High Dependency' WHEN pct>=.5 THEN 'Medium Dependency' WHEN pct>=.3 THEN 'Low Dependency' ELSE 'Minimal Dependency' END", "CASE WHEN total_vendor_spend>=(SELECT quantile_cont(total_vendor_spend,.9) FROM agg) THEN 'Critical Dependency' WHEN total_vendor_spend>=(SELECT quantile_cont(total_vendor_spend,.7) FROM agg) THEN 'High Dependency' WHEN total_vendor_spend>=(SELECT quantile_cont(total_vendor_spend,.5) FROM agg) THEN 'Medium Dependency' WHEN total_vendor_spend>=(SELECT quantile_cont(total_vendor_spend,.3) FROM agg) THEN 'Low Dependency' ELSE 'Minimal Dependency' END",I,'契约按支出percentile阈值含等号分类，agent用percent_rank。')
